SELECT ano,        CASE pmod(dayofweek(data_acidente)+5,7) WHEN 0 THEN 'Segunda' WHEN 1 THEN 'Terça'             WHEN 2 THEN 'Quarta' WHEN 3 THEN 'Quinta' WHEN 4 THEN 'Sexta'             WHEN 5 THEN 'Sábado' ELSE 'Domingo' END AS dia_semana,        MIN(pmod(dayofweek(data_acidente)+5,7)) AS ordem,        COUNT(*) AS acidentes, SUM(obito) AS obitos FROM {{ source('silver', 'acidentes') }} WHERE ano IS NOT NULL AND data_acidente IS NOT NULL GROUP BY 1,2
